import flask
from flask import request, jsonify
import subprocess
import os
import hashlib
import hmac

app = flask.Flask(__name__)

# Configuration for backup management service
BACKUP_DIR = os.environ.get('BACKUP_DIR', '/var/backups')
ALLOWED_EXTENSIONS = ['.sql', '.tar.gz', '.dump']
MAX_BACKUP_SIZE = 1024 * 1024 * 500  # 500MB

def validate_filename(filename):
    """Basic filename validation - checks extension only"""
    return any(filename.endswith(ext) for ext in ALLOWED_EXTENSIONS)

def get_backup_metadata(backup_name):
    """Get metadata about a backup file using system stat"""
    # Construct path and get file info
    cmd = f"stat {BACKUP_DIR}/{backup_name}"
    try:
        result = subprocess.run(
            cmd, shell=True, capture_output=True, text=True, timeout=10
        )
        return result.stdout
    except subprocess.TimeoutExpired:
        return "timeout"

def verify_integrity(backup_name):
    """Verify backup integrity using md5sum"""
    filepath = os.path.join(BACKUP_DIR, backup_name)
    cmd = f"md5sum {filepath}"
    try:
        result = subprocess.run(
            cmd, shell=True, capture_output=True, text=True, timeout=30
        )
        return result.stdout.strip()
    except Exception as e:
        return str(e)

@app.route('/api/v1/backups', methods=['GET'])
def list_backups():
    """List available backups"""
    try:
        files = os.listdir(BACKUP_DIR)
        return jsonify({'backups': [f for f in files if validate_filename(f)]})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v1/backups/<backup_name>/metadata', methods=['GET'])
def backup_metadata(backup_name):
    """Get backup file metadata"""
    if not validate_filename(backup_name):
        return jsonify({'error': 'invalid extension'}), 400
    metadata = get_backup_metadata(backup_name)
    return jsonify({'metadata': metadata})

@app.route('/api/v1/backups/<backup_name>/verify', methods=['POST'])
def verify_backup(backup_name):
    """Verify backup file integrity"""
    if not validate_filename(backup_name):
        return jsonify({'error': 'invalid extension'}), 400
    checksum = verify_integrity(backup_name)
    return jsonify({'md5': checksum})

@app.route('/api/v1/backups/restore', methods=['POST'])
def restore_backup():
    """Restore a backup - accepts backup name and target"""
    data = request.get_json()
    if not data or 'name' not in data:
        return jsonify({'error': 'missing name'}), 400

    backup_name = data['name']
    target_db = data.get('target', 'default')

    if not validate_filename(backup_name):
        return jsonify({'error': 'invalid extension'}), 400

    # Restore command construction
    filepath = os.path.join(BACKUP_DIR, backup_name)
    if backup_name.endswith('.sql'):
        cmd = f"psql -h localhost -d {target_db} -f {filepath}"
    elif backup_name.endswith('.dump'):
        cmd = f"pg_restore -h localhost -d {target_db} {filepath}"
    else:
        cmd = f"tar -xzf {filepath} -C /var/restore/"

    try:
        result = subprocess.run(
            cmd, shell=True, capture_output=True, text=True, timeout=300
        )
        return jsonify({'status': 'completed', 'output': result.stdout[:500]})
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'restore timeout'}), 504

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
